import { VariableSizeList } from 'react-window';

const getItemSize = (index) => {
  // Different items have different heights
  if (index % 3 === 0) return 80;  // Large items
  if (index % 3 === 1) return 50;  // Medium items
  return 35;  // Small items
};

const Row = ({ index, style }) => (
  <div style={style}>
    Variable height item {index}
  </div>
);

function VariableHeightList() {
  return (
    <VariableSizeList
      height={400}
      width={500}
      itemSize={getItemSize}
      itemCount={1000}
    >
      {Row}
    </VariableSizeList>
  );
}

import { FixedSizeList } from 'react-window';
import { useState, useCallback } from 'react';

function InfiniteVirtualList() {
  const [items, setItems] = useState(Array.from({ length: 100 }, (_, i) => i));
  const [isLoading, setIsLoading] = useState(false);

  const loadMoreItems = useCallback(() => {
    if (isLoading) return;
    setIsLoading(true);

    // Simulate API call
    setTimeout(() => {
      const newItems = Array.from({ length: 100 }, (_, i) => items.length + i);
      setItems(prev => [...prev, ...newItems]);
      setIsLoading(false);
    }, 1000);
  }, [isLoading, items.length]);

  const isItemLoaded = (index) => !!items[index];

  const Row = ({ index, style }) => {
    if (!isItemLoaded(index)) {
      return <div style={style}>Loading...</div>;
    }
    return <div style={style}>Item {items[index]}</div>;
  };

  return (
    <FixedSizeList
      height={400}
      width={500}
      itemSize={35}
      itemCount={items.length + 100} // Extra space for loading
      onItemsRendered={({ visibleStopIndex }) => {
        if (visibleStopIndex >= items.length - 50) {
          loadMoreItems();
        }
      }
    >
      {Row}
    </FixedSizeList>
  );
}

import { List } from 'react-virtualized';

function VirtualizedListAlternative() {
  const items = Array.from({ length: 10000 }, (_, i) => i);

  const rowRenderer = ({
    index,
    key,
    style
  }) => (
    <div key={key} style={style}>
      Item {index}
    </div>
  );

  return (
    <List
      width={500}
      height={400}
      rowCount={items.length}
      rowHeight={35}
      rowRenderer={rowRenderer}
    />
  );
}

// Performance monitoring for virtualized lists
function measureListPerformance() {
  const start = performance.now();

  // Measure DOM node count
  const domNodes = document.querySelectorAll('*').length;
  console.log('DOM nodes:', domNodes);

  // Measure memory usage (if available)
  if (performance.memory) {
    console.log('Memory used:', performance.memory.usedJSHeapSize);
  }

  // Measure render time
  const renderTime = performance.now() - start;
  console.log('Render time:', renderTime);

  // Monitor scroll performance
  let lastScrollTime = 0;
  const scrollHandler = () => {
    const now = performance.now();
    const scrollDelta = now - lastScrollTime;
    lastScrollTime = now;

    if (scrollDelta > 16) { // More than one frame
      console.warn('Scroll jank detected:', scrollDelta);
    }
  };

  window.addEventListener('scroll', scrollHandler);
  return () => window.removeEventListener('scroll', scrollHandler);
}
